Mesh<Point, double> mesh;
using Vertex_handle = RT::Vertex_handle;
using Face_handle = RT::Face_handle;

std::map<Vertex_handle, Point> dual_points;
for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    Point dual_pt(vit->point().x(), vit->point().y());
    dual_points[vit] = dual_pt;
}

for (auto fit = rt.finite_faces_begin(); fit != rt.finite_faces_end(); ++fit) {
    double area = 0.0;
    std::vector<Point> edge_vertices;

    for (int i = 0; i < 3; i++) {
        Vertex_handle va = fit->vertex(i);
        Vertex_handle vb = fit->vertex((i+1)%3);
        Vertex_handle vc = fit->vertex((i+2)%3);

        if (!va->info().is_valid() || !vb->info().is_valid() || !vc->info().is_valid())
            continue;

        Point pa = dual_points[va];
        Point pb = dual_points[vb];
        Point pc = dual_points[vc];

        double fab = std::sqrt(CGAL::squared_distance(pa, pb));
        double fbc = std::sqrt(CGAL::squared_distance(pb, pc));
        double fca = std::sqrt(CGAL::squared_distance(pc, pa));

        if (fab < threshold || fbc < threshold || fca < threshold) {
            edge_vertices.push_back(pa);
            edge_vertices.push_back(pb);
            edge_vertices.push_back(pc);
            area += fbc;
        }
    }

    for (size_t i = 0; i < edge_vertices.size(); i += 2) {
        if (i + 1 < edge_vertices.size()) {
            mesh.add_segment(edge_vertices[i], edge_vertices[i+1]);
        }
    }

    mesh.add_face_area(area);
}

return mesh;
// END_CODE

